// IMAP message → Mortar's inbound-email envelope (see fromInboundEmail in src/core/events.js).
// Only reshapes fields: Mortar dedupes on messageId and spots auto-replies from the headers.
const address = (v) => (typeof v === 'string' ? v : v?.value?.[0]?.address ?? v?.text ?? '');
return $input.all().map(({ json: m }) => {
  const headers = m.metadata ?? m.headers ?? {};
  const payload = {
    event: 'email.received',
    messageId: m.messageId ?? headers['message-id'] ?? `${m.date}|${address(m.from)}|${m.subject ?? ''}`,
    from: address(m.from),
    to: address(m.to),
    subject: m.subject ?? '',
    text: m.textPlain ?? m.text ?? '',
    headers,
    date: m.date,
  };
  return { json: { payload: JSON.stringify(payload) } };
});
